extra_probe_sources.engine:
extends SceneTree

const Adapter = preload("res://infrastructure/engine/adapter.gd")
const Scope := "qa-generation"
var engine: Adapter
var checks := []

func check(value: bool, label: String) -> void:
	checks.append({"label":label,"passed":value})
	print("QA ",label," ",value)

func row(g: int, x: float) -> Dictionary:
	return {"handle":{"index":43,"generation":g},"team_key":0,"position":Vector3(x,0,0),"facing":Vector3.RIGHT,"shield":false}

func ids(x: int) -> Array:
	var result := engine.field_sweep(Scope,[{"from":[x*1000-800,1050,0],"to":[x*1000+800,1050,0]}],22)
	if not result.ok: return ["error"]
	return result.value.map(func(h): return h.target)

func stale(result: Dictionary) -> bool:
	return not result.ok and result.error.code=="StaleVersion"

func _initialize() -> void:
	run.call_deferred()

func run() -> void:
	engine=Adapter.new(root)
	var scope := engine.open_scope(Scope)
	var loaded := engine.load_scene({"id":"field:scene/river_plain","simulation_scene":"res://content/base/field/river_plain.tscn"},scope.value)
	check(loaded.ok,"actual arena")
	await physics_frame
	await physics_frame
	var v5 := row(5,2)
	var v9 := row(9,12)
	check(engine.field_stage_bodies(Scope,[v5]).ok and engine.field_commit_bodies(Scope).ok,"commit generation five")
	check(engine.field_stage_bodies(Scope,[v9]).ok and ids(12)==[v9.handle] and ids(2)==[],"tentative higher generation physical body")
	check(engine.field_rollback_bodies(Scope).ok and ids(12)==[] and ids(2)==[v5.handle],"rolled-back physical identity restored immediately")
	check(stale(engine.field_stage_bodies(Scope,[row(4,-12)])) and ids(-12)==[],"older than restored committed generation is rejected")
	var v6 := row(6,6)
	check(engine.field_stage_bodies(Scope,[v6]).ok and engine.field_commit_bodies(Scope).ok and ids(6)==[v6.handle],"discarded generation nine does not block generation six retry")
	check(stale(engine.field_stage_bodies(Scope,[v5])) and ids(2)==[] and ids(6)==[v6.handle],"superseded generation five rejected with position intact")
	check(engine.field_stage_bodies(Scope,[]).ok and engine.field_commit_bodies(Scope).ok and ids(6)==[],"physical retirement")
	check(stale(engine.field_stage_bodies(Scope,[v6])) and ids(6)==[],"retired generation six cannot reappear")
	engine.release_scope(Scope)
	var failed := checks.filter(func(c):return not c.passed)
	print("QA_ENGINE_CHECKS=",checks.size()," failures=",failed.size())
	quit(0 if failed.is_empty() else 1)

extra_probe_sources.ai:
extends SceneTree

const AI = preload("res://mission/ai/ports/field_ai.gd")
var checks := []

func check(value: bool, label: String) -> void:
	checks.append({"label":label,"passed":value})
	print("QA ",label," ",value)

func unit(g: int, x: float) -> Dictionary:
	return {"handle":{"index":0,"generation":g},"team_key":0,"formation_id":0,"role":"infantry","position":Vector3(x,0,0),"hp":80,"control_revision":1,"order_revision":1,"urgent":true}

func pick(ai: RefCounted) -> Dictionary:
	for job in ai.schedule().value.jobs:
		if job.layer=="individual": return job
	return {}

func stale(result: Dictionary) -> bool:
	return not result.ok and result.error.code=="StaleVersion"

func _initialize() -> void:
	var ai := AI.new("qa-grant",func(_a,_b): return true,5)
	var v4 := unit(4,4)
	var v8 := unit(8,8)
	check(ai.begin_tick().ok and ai.publish(1,1,[v4]).ok,"publish generation four")
	var initial := pick(ai)
	ai.commit_tick()
	check(ai.begin_tick().ok and ai.publish(2,1,[v8]).ok,"tentative generation eight")
	var dead := pick(ai)
	var escaped: Dictionary = dead.duplicate(true)
	ai.rollback_tick()
	check(ai.sense(v4.handle).ok and not ai.sense(v8.handle).ok,"rolled-back generations visible only at committed birth")
	check(stale(ai.collect(escaped,[])) and ai.collect(initial,[]).ok,"abandoned copied worker denied and untouched original grant restored")
	var drained: Array=ai.drain().value
	check(drained.size()==1 and is_same(drained[0].job,initial),"restored grant executes exactly once")
	check(ai.begin_tick().ok and ai.publish(2,1,[v8]).ok,"identical tick and generation retry")
	var retry := pick(ai)
	check(not retry.is_empty() and retry.id!=escaped.id and retry.stamp==escaped.stamp and retry.subject==escaped.subject,"same public stamp, distinct capability")
	check(stale(ai.collect(dead,[])) and stale(ai.collect(escaped,[])) and ai.collect(retry,[]).ok,"late originals and copies cannot consume replacement")
	var rows: Array=ai.drain().value
	check(rows.size()==1 and is_same(rows[0].job,retry) and stale(ai.collect(retry,[])),"replacement accepted once")
	ai.commit_tick()
	check(stale(ai.publish(3,1,[v4])) and not ai.sense(v4.handle).ok and ai.sense(v8.handle).ok,"old generation rejected after committed replay")
	var failed := checks.filter(func(c):return not c.passed)
	print("QA_AI_CHECKS=",checks.size()," failures=",failed.size())
	quit(0 if failed.is_empty() else 1)
